    avpinguino: () => band('#8fd6ff', 7) + [-120, -105, -90, -75, -60].map((d, i) => { const [x, y] = at(d, 50); const h = i % 2 ? 7 : 11; return `<path d="M${(x - 3).toFixed(1)} ${y.toFixed(1)}L${x.toFixed(1)} ${(y + h).toFixed(1)}L${(x + 3).toFixed(1)} ${y.toFixed(1)}z" fill="#eefcff" stroke="${K}" stroke-width="1.4" stroke-linejoin="round"/>`; }).join('') + many('cubohielo', [-160, -20, 50, 130], 56, 0.5, 'r-bob') + twinkle([90], 56, '#fff', 4.6),
    avpanda: () => band('#5fae5a') + stitch('#e6f8d8') + many('bambu', [180, 0], 54, 0.95, 'r-sway') + put('onigiri', 90, 54, 0.62, 'r-hop') + many('trebol', [-90], 56, 0.4, ''),
