    avpulpo: () => band('#8a5cf0') + many('tentaculo', [125, 55], 47, 0.72, 'r-sway', (d) => (d > 90 ? 0 : 0)) + many('burbuja', [-150, -110, -60, -20], 56, 0.38, 'r-bob'),
    avabeja: () => band('#ffc83d', 7) + `<circle cx="70" cy="70" r="55" fill="none" stroke="#e8a12a" stroke-width="2" stroke-dasharray="4 4"/>` + [-115, -65].map((d, i) => { const [x, y] = at(d, 50); return `<path class="r-bob" style="animation-delay:${i * 0.5}s" d="M${(x - 4).toFixed(1)} ${y.toFixed(1)}q4 12 0 14a4 4 0 0 0 8 0q-4-2 0-14z" fill="#ffb31a" stroke="${K}" stroke-width="1.4"/>`; }).join('') + put('panal', -90, 56, 0.6, '') + many('margarita', [30, 150], 56, 0.5, 'r-sway') + put('miel', 90, 55, 0.5, 'r-bob'),
