    avastro: () => band('#3a2a99') + stitch('#c9bff0') + spin(twinkle([-150, -110, -60, 20, 160], 55, '#fff6c8'), true) + put('casco', 60, 55, 0.6, 'r-bob') + orbit('estacion', 0.6, 66, 22, -20, 7),
    avalien: () => band('#9be86a') + stitch('#e6ffd0') + many('antena', [-125, -55], 57, 0.75, 'r-sway') + spin(many('roca', [40, 140], 56, 0.45, 'r-roll')) + twinkle([90, 180, 0], 56, '#c8ff8a'),
    avdino: () => [-150, -130, -110, -90, -70, -50, -30].map((d) => { const [x, y] = at(d, 59), [x1, y1] = at(d - 7, 57), [x2, y2] = at(d + 7, 57), [tx, ty] = at(d, 67); return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)}L${tx.toFixed(1)} ${ty.toFixed(1)}L${x2.toFixed(1)} ${y2.toFixed(1)}z" fill="#ff9c5b" stroke="${K}" stroke-width="1.6" stroke-linejoin="round"/>`; }).join('') + band('#5fbf5a', 7) + stitch('#e6f8d8') + many('huevo', [60, 90, 120], 56, 0.55, 'r-sway'),
    avfantasma: () => band('#c9bff0') + stitch('#fff') + many('linterna', [-140, -40, 40, 140], 56, 0.55, 'r-sway') + twinkle([-90, 90], 56, '#ffe9a8'),
