  const at2 = (ico, x, y, k = 1, rot = 0) => `<g transform="translate(${x - 16 * k} ${y - 16 * k}) rotate(${rot} ${16 * k} ${16 * k}) scale(${k})">${ICONS[ico]()}</g>`;
